def test_semantic_completeness_literal_oracles_and_targeted_mutations():
    mapping = section(EXPECTED_DOC, "Mapping input")
    keys = section(EXPECTED_DOC, "Keys")
    text = section(EXPECTED_DOC, "Text fields")
    assert EXPECTED_MAPPING_SIGNATURE in mapping
    assert EXPECTED_VALIDATION_SIGNATURE in section(EXPECTED_DOC, "Validation order")
    assert numbered(keys)[:36] == EXPECTED_REQUIRED_KEYS
    assert numbered(keys)[36:] == EXPECTED_OPTIONAL_KEYS
    assert numbered(text)[:22] == EXPECTED_REQUIRED_TEXT
    assert numbered(text)[22:] == EXPECTED_NULLABLE_TEXT
    assert all(rule in keys for rule in EXPECTED_KEY_ORDER)
    assert all(rule in mapping for rule in EXPECTED_ENUM_ADAPTATION)
    assert numbered(section(EXPECTED_DOC, "Stratification")) == []
    assert all(axis in section(EXPECTED_DOC, "Stratification") for axis in EXPECTED_AXES)
    assert EXPECTED_BASELINE_TUPLE in section(EXPECTED_DOC, "Baseline comparison")
    assert all(rule in section(EXPECTED_DOC, "Provenance") for rule in EXPECTED_PROVENANCE_RULES)
    assert all(rule in section(EXPECTED_DOC, "Artifact-policy matrix") for rule in EXPECTED_POLICY_RULES)
    assert all(rule in section(EXPECTED_DOC, "Representation matrix") for rule in EXPECTED_DEPENDENCY_RULES)
    assert all(rule in section(EXPECTED_DOC, "Status and supersession") for rule in EXPECTED_STATUS_RULES)
    mutations = [
        (mapping, "mapping: object", "mapping: dict"),
        (keys, "type(key) is str", "isinstance(key, str)"),
        (text, "type(value) is str", "isinstance(value, str)"),
        (section(EXPECTED_DOC, "Stratification"), "An empty tuple is valid", "An empty tuple is invalid"),
        (section(EXPECTED_DOC, "Baseline comparison"), "BaselineType.CLIMATOLOGY", "BaselineType.PERSISTENCE"),
        (section(EXPECTED_DOC, "Provenance"), "Valid duplicates", "Invalid duplicates"),
        (section(EXPECTED_DOC, "Artifact-policy matrix"), "exactly one `INAPPLICABLE_POLICY_FIELDS_PRESENT`", "two `INAPPLICABLE_POLICY_FIELDS_PRESENT`"),
        (section(EXPECTED_DOC, "Status and supersession"), "exactly once", "more than once"),
    ]
    for body, old, new in mutations:
        assert old in body and body.replace(old, new, 1) != body


def test_non_goals_and_static_test_safety():
    non_goals = section(EXPECTED_DOC, "Non-goals")
    for item in ["score calculation", "diagnostic calculation", "probability generation", "label joining", "split execution", "baseline execution", "evaluation-result creation", "claim creation or evaluation", "evidence-gate evaluation", "data or corpus creation", "source fetching", "persistence", "reporting", "simulation", "market comparison execution", "trading", "runtime orchestration", "autonomy"]:
        assert item in non_goals
    tree = ast.parse(SELF_PATH.read_text(encoding="utf-8"))
    imports = {node.names[0].name.split(".")[0] for node in tree.body if isinstance(node, (ast.Import, ast.ImportFrom))}
    assert imports <= {"ast", "pathlib", "re"}
    forbidden = {"open", "exec", "eval", "compile", "__import__", "system", "popen", "run", "check_call", "check_output", "putenv", "setenv"}
    calls = {node.func.id for node in ast.walk(tree) if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)}
    assert not calls & forbidden


def test_direct_allowlist_registration_and_observed_counts():
    source = ALLOWLIST_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    assignment = next(node for node in tree.body if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id == "ALLOWED_MARKET_ID_OCCURRENCE_LINES")
    assert isinstance(assignment.value, ast.Call) and len(assignment.value.args) == 1
    allowlist = ast.literal_eval(assignment.value.args[0])
    downstream_assignment = next(node for node in tree.body if isinstance(node, ast.Assign) and any(isinstance(target, ast.Name) and target.id == "_ARCH_ALIGN_03_DOWNSTREAM_ARTIFACTS" for target in node.targets))
    downstream = ast.literal_eval(downstream_assignment.value)
    for path, count in EXPECTED_ALLOWLIST_COUNTS.items():
        assert isinstance(count, int) and type(allowlist[path]) is int
        assert allowlist[path] == count
        assert source.count(f'"{path}"') == 2
        assert list(downstream).count(path) == 1
        assert (ROOT / path).read_text(encoding="utf-8").count("market_id") == count
    assert len(set(EXPECTED_ALLOWLIST_COUNTS)) == 2
